@extends('layouts.app') @section('title','Calendar') @section('content')<x-page-header title="Booking calendar"/><div class="content-card" id="calendar"></div>@endsection @push('scripts')<script>const events=@json($events),root=document.getElementById('calendar');events.forEach(e=>root.insertAdjacentHTML('beforeend',`<a class="d-block border rounded p-3 mb-2 text-decoration-none" href="${e.url}"><b>${e.date}</b> · ${e.time} · ${e.title}</a>`));if(!events.length)root.innerHTML='<p>No bookings scheduled.</p>';</script>@endpush
